Translate("zhCN", "swamp-of-sorrows", {
	title = "悲伤沼泽",
	aliases = { "沼泽" },
	sections = {
		{
			title = "概述",
			text = [=[悲伤沼泽是{link:eastern-kingdoms}东部王国{/link}东南部一片低陷的土地，满是黑水、垂挂的苔藓和下个不停的雨。它位于{link:deadwind-pass}逆风小径{/link}以东、{link:blasted-lands}诅咒之地{/link}以北，东岸受着禁忌之海的拍打。这里的树木齐膝浸在水中，道路消失在泥沼之下，水塘里孕育着鳄鱼、巨型蜘蛛和会行走的活水草团。从来没有哪个王国驯服过它。{link:horde}部落{/link}的{link:orcs}兽人{/link}在它的中心据守着一座要塞，一小群流亡者依附在它的西部边缘，{link:murlocs}鱼人{/link}沿着海岸成群出没，而绿龙则默默守望着一座湖泊，湖底沉睡着一座{link:trolls}巨魔{/link}神庙。]=],
		},
		{
			title = "起源",
			text = [=[没有任何史书记载是谁最先为这片沼泽命名，也没有记载它为何被称为悲伤之地。人们记得的是，这里长久以来一直是流亡者的土地。当古拉巴什{link:trolls}巨魔{/link}推翻他们的血神{link:hakkar}哈卡{/link}时，他们把他的祭司阿塔莱赶出了南方的丛林。阿塔莱向北逃进了这片沼泽。他们在这里建起了一座巨大的神庙，即{link:temple-of-atal-hakkar}阿塔哈卡神庙{/link}，他们打算在那里把他们的神重新召唤到这个世界上。{red:ysera}伊瑟拉{/red}的绿龙军团不允许这样做。巨龙们摧毁了神庙，把它沉入{link:pool-of-tears}泪水之池{/link}的水底，它至今仍躺在那里。没有任何史书给出那一年。

沼泽的南边曾是黑色沼泽。{link:dark-portal}黑暗之门{/link}正是在那里开启，{link:orcs}兽人{/link}{link:horde}部落{/link}也正是从那里出发，在{link:first-war}第一次战争{/link}中向{link:azeroth}艾泽拉斯{/link}王国开战。这片沼泽是部落在这个世界上的第一个邻居。]=],
		},
		{
			title = "当今",
			text = [=[这片沼泽是争夺之地。大酋长{link:thrall}萨尔{/link}在它的中心据守着{link:stonard}斯通纳德{/link}要塞，他的{link:orcs}兽人{/link}派出了使者，去查明那座{link:temple-of-atal-hakkar}沉没的神庙{/link}遭遇了什么。{link:alliance}联盟{/link}在这里没有城镇。它的商队只是在从{link:duskwood}暮色森林{/link}到{link:nethergarde-keep}守望堡{/link}的漫长道路上经过这里，许多商队没能抵达。在北方，一群被称为失落者的人袭击任何在他们村庄附近游荡的人。在西方，一队与他们同血统却没有他们那般疯狂的德莱尼流亡者躲在{link:the-harborage}避难营{/link}。沿着东岸，{link:murlocs}鱼人{/link}一季比一季更加大胆。而在这一切之上，绿龙盘旋着、等待着，守卫着神庙，以防它的祭司再次蠢动的那一天。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:stonard}斯通纳德{/link}的{link:orcs}兽人{/link}。{/b}{link:horde}部落{/link}的战士、斥候和商人，他们据守着沼泽中唯一的要塞，守卫着它的道路和海岸。
• {b}{link:the-harborage}避难营{/link}的德莱尼。{/b}西部的一小群流亡者，他们从远方来到{link:azeroth}艾泽拉斯{/link}，如今却惧怕自己的亲族。
• {b}失落者。{/b}德莱尼的亲族，被把他们带到这里的漫长旅程逼疯了。他们占据着北部的{link:fallow-sanctuary}农田避难所{/link}。
• {b}绿龙军团。{/b}伊瑟拉军团的雏龙、龙人和鳞刃守卫着{link:pool-of-tears}泪水之池{/link}及其周围的土地。一条名叫{link:itharius}伊萨里奥斯{/link}的龙在西南部有一个洞穴。
• {b}鱼人。{/b}{link:misty-reed-strand}芦苇海滩{/link}的{link:murlocs}鱼人{/link}部族沿着东海岸成群出没。
• {b}沼泽中的野兽。{/b}锯齿鳄鱼、美洲豹、黑豹、巨型蜘蛛，以及被称为沼泽行者和纠缠恐魔的行走水草。
• {b}阿塔莱。{/b}{link:hakkar}哈卡{/link}的{link:trolls}巨魔{/link}祭司仍住在泪水之池下方那座{link:temple-of-atal-hakkar}沉没的神庙{/link}里。]=],
		},
		{
			title = "历史",
			text = [=[• {b}阿塔莱的流亡。{/b}被古拉巴什驱逐之后，{link:hakkar}哈卡{/link}的祭司们在沼泽中建起了他们的神庙。
• {b}神庙的沉没。{/b}绿龙军团摧毁了神庙并将其淹没，使血神无法通过它归来。
• {b}{link:first-war}第一次战争{/link}。{/b}{link:dark-portal}黑暗之门{/link}在南边的黑色沼泽开启，{link:horde}部落{/link}第一次踏上这个世界，就在沼泽的边缘。
• {b}{link:stonard}斯通纳德{/link}的建立。{/b}没有任何史书记载{link:orcs}兽人{/link}何时建起了斯通纳德。如今它是大酋长在南方的要塞，依靠一条从{link:stranglethorn-vale}荆棘谷{/link}的{link:grom-gol-base-camp}格罗姆高营地{/link}延伸而来的漫长补给线维持。
• {b}当今。{/b}部落研究着那座神庙，{link:alliance}联盟{/link}催促着它的商队匆匆经过，而巨龙们在等待。]=],
		},
		{
			title = "沼泽传说",
			text = [=[• {link:ironforge}铁炉堡{/link}的{link:explorers-league}探险者协会{/link}长久以来一直在寻找{link:temple-of-atal-hakkar}阿塔哈卡神庙{/link}。协会的一位老{link:dwarves}矮人{/link}曾骑着狮鹫飞越沼泽，却从未找到它。人们最终是从地面上发现它的，它淹没在{link:pool-of-tears}泪水之池{/link}的水下。
• 德莱尼把一种神圣的水晶称为德莱尼晶石。据说它来自一个群山飞翔、恶魔统治的地方。{link:desolace}凄凉之地{/link}的一位{link:centaurs}半人马{/link}萨满曾派人到沼泽来取一块这样的碎片。
• {link:kirin-tor}肯瑞托{/link}的一位信使曾在这里丢失了一篇珍贵的论文。那是{link:khadgar}卡德加{/link}所写、要送往{link:nethergarde-keep}守望堡{/link}的论文，沼泽中的行走水草从他手中夺走了它。
• 在沼泽西部一座旧桥下，靠近从{link:deadwind-pass}逆风小径{/link}过来的道路，有人为寻宝者留下了潦草的谜语。这些谜语提到一个名叫科泰罗的人，它们引人渡过大海，又再度归来。
• 地精会出高价收购梦尘，一种从沼泽中的雏龙身上收集到的闪光粉末。]=],
		},
	},
})

Translate("zhCN", "stonard", {
	title = "斯通纳德",
	sections = {
		{
			title = "概述",
			text = [=[斯通纳德是{link:horde}部落{/link}在{link:swamp-of-sorrows}沼泽{/link}中心的要塞。它那由{link:blackrock-mountain}黑石{/link}和粗木筑成的城墙耸立在水塘之间的干地上，它的塔楼俯瞰着绵延数里的芦苇和水面。这是大酋长在{link:eastern-kingdoms}东部王国{/link}南部最坚固的据点。传令兵从这里把命令送往{link:blasted-lands}诅咒之地{/link}，信使把报告送到{link:badlands}废土{/link}的{link:kargath}卡加斯{/link}，双足飞龙向北飞去。各行各业的训练师在城墙之内设有他们的厅堂，一位商人把海岸的肉类运回{link:orgrimmar}奥格瑞玛{/link}。]=],
		},
		{
			title = "城墙之内",
			text = [=[斯通纳德关着一名囚犯。一个{link:alliance}联盟{/link}的{link:humans}人类{/link}间谍被看押着，他声称知道一桩牵连远超联盟本身的背叛。这座要塞还庇护着大酋长的使者{link:fel-zerul}费泽鲁尔{/link}，他被派来查明那座{link:temple-of-atal-hakkar}沉没神庙{/link}的命运。]=],
		},
	},
})

Translate("zhCN", "pool-of-tears", {
	title = "泪水之池",
	sections = {
		{
			title = "概述",
			text = [=[泪水之池是{link:swamp-of-sorrows}沼泽{/link}东部一片宽阔而平静的湖泊。断裂的石柱和古老阶梯的残桩从它的浅水中升起。{link:temple-of-atal-hakkar}阿塔哈卡神庙{/link}就躺在它的水下，绿龙军团摧毁并淹没了它，使{link:hakkar}哈卡{/link}的祭司永远无法完成他们的召唤。在湖岸的泥中仍能找到阿塔莱的遗物：神像、神物和雕刻过的石头。伊瑟拉军团的巨龙守卫着这座湖。龙人和鳞刃站在湖岸上，不容任何人无故靠近。阿塔莱仍住在下面那些淹没的厅堂中。]=],
		},
	},
})

Translate("zhCN", "fallow-sanctuary", {
	title = "农田避难所",
	sections = {
		{
			title = "概述",
			text = [=[农田避难所是失落者的村庄，位于{link:swamp-of-sorrows}沼泽{/link}北部。它那些用芦苇和兽皮搭成的小屋围着炊火挤在一起，它的猎人、渔夫和先知从这里出发，深入沼泽。失落者看起来和{link:the-harborage}避难营{/link}的德莱尼一样，因为他们曾是同一个民族。但把他们带到{link:azeroth}艾泽拉斯{/link}的漫长旅程摧毁了他们的心智，如今他们会抓住或杀死任何误入附近的人。偷来的东西堆积在他们的小屋之间：从避难营夺来的神圣的德莱尼晶石，以及一支{link:alliance}联盟{/link}商队的马车。他们的酋长统治着这座村庄。一个名叫{link:ongeku}盎格库尔{/link}的失落者把一块德莱尼晶石碎片据为己有，留在那里。]=],
		},
	},
})

Translate("zhCN", "the-harborage", {
	title = "避难营",
	aliases = { "避难所营地" },
	sections = {
		{
			title = "概述",
			text = [=[避难营是{link:swamp-of-sorrows}沼泽{/link}西北部的一个小小避难地，一队德莱尼流亡者在那里安了家。他们人数很少，装备简陋。他们的亲族，即{link:fallow-sanctuary}农田避难所{/link}的失落者，偷走了他们神圣的水晶，一个名叫{link:noboru-the-cudgel}诺博鲁{/link}的蛮人拿着他的大棒追猎了他们好几个月。{link:magtoor}玛格图尔{/link}代表流亡者说话，一位名叫马{link:satyrs}萨特{/link}·坦德的制皮匠在他们中间干活。他们欢迎任何旗帜下怀着和平而来的旅行者，因为他们没有力量把任何人拒之门外。]=],
		},
	},
})

Translate("zhCN", "itharius-s-cave", {
	title = "伊萨里奥斯的洞穴",
	sections = {
		{
			title = "概述",
			text = [=[伊萨里奥斯的洞穴位于{link:swamp-of-sorrows}沼泽{/link}的遥远西南部，隐藏在靠近{link:blasted-lands}诅咒之地{/link}边界的滴水树木之间。它是{link:itharius}伊萨里奥斯{/link}的巢穴，他是一条绿龙军团的龙。他的同族中年幼的雏龙在洞口周围的沼泽中睡觉和嬉戏，从它们翅膀上落下的尘埃在昏暗中闪烁如霜。很少有人不请自来。来到这里的人，通常是在寻求只有巨龙才能给予的帮助。]=],
		},
	},
})

Translate("zhCN", "misty-reed-strand", {
	title = "芦苇海滩",
	aliases = { "芦苇哨岗" },
	sections = {
		{
			title = "概述",
			text = [=[芦苇海滩是{link:swamp-of-sorrows}沼泽{/link}东部漫长的海岸，沼泽在那里让位于沙滩和禁忌之海灰色的浪花。{link:murlocs}鱼人{/link}挤满了它的海滩：袭击者、食肉者、喷墨者和先知。巨型爬行者在岩石间疾走，锯齿钳嘴龟潜伏在浅水中。在它的南端矗立着芦苇哨岗，一座{link:horde}部落{/link}的小营地。营地的{link:orcs}兽人{/link}守望着大海，一旦鱼人大举来犯，他们就会向{link:stonard}斯通纳德{/link}发出警报。]=],
		},
	},
})

Translate("zhCN", "misty-valley", {
	title = "迷雾谷",
	sections = {
		{
			title = "概述",
			text = [=[迷雾谷是{link:swamp-of-sorrows}沼泽{/link}的西大门，{link:deadwind-pass}逆风小径{/link}的死寂土地在那里向下倾斜，没入沼泽。无论何时，雾气都浓浓地笼罩着它的洼地。沼泽的行走水草在这里最为强大：长满苔藓的老沼泽行者，还有一个被{link:orcs}兽人{/link}称为泥沼之王的巨物，它在遥远的西部水塘中游荡。来自西方的旅行者首先穿过这座{link:stranglethorn-vale}山谷{/link}。它是沼泽对他们关于前路的警告。]=],
		},
	},
})

Translate("zhCN", "sorrowmurk", {
	title = "忧伤湿地",
	sections = {
		{
			title = "概述",
			text = [=[忧伤湿地是遥远东部的{link:the-marshlands}沼泽地{/link}，位于{link:pool-of-tears}泪水之池{/link}与大海之间。它是这片阴郁土地上最阴郁的角落。绿龙军团中最古老的龙人在这里守望，据说名为维尔玛克的龙人队长指挥着神庙周围的巡逻队。暗影黑豹在芦苇中潜行。就连{link:stonard}斯通纳德{/link}的{link:orcs}兽人{/link}，若非不得已，也很少走这条路。]=],
		},
	},
})

Translate("zhCN", "stagalbog", {
	title = "雄鹿沼泽",
	aliases = { "雄鹿沼泽洞穴" },
	sections = {
		{
			title = "概述",
			text = [=[雄鹿沼泽是{link:swamp-of-sorrows}沼泽{/link}东南部一片蔓延的腐烂水塘。由水草和根须组成的纠缠恐魔在水中跋涉，绿龙军团的鳞刃在岸边巡逻。靠近海岸的山丘中开着一个洞穴。那是{link:murlocs}鱼人{/link}的巢穴，据说它们的首领，那个被{link:orcs}兽人{/link}称为{link:swamp-talker}沼泽空谈者{/link}的家伙，就住在里面。{link:horde}部落{/link}的命令随着夺走它们的鱼人一起消失在了那个洞穴里。]=],
		},
	},
})

Translate("zhCN", "splinterspear-junction", {
	title = "断矛路口",
	sections = {
		{
			title = "概述",
			text = [=[断矛路口是{link:swamp-of-sorrows}沼泽{/link}西部的一个道路交汇处。在这里，来自{link:deadwind-pass}逆风小径{/link}的道路与向南通往{link:blasted-lands}诅咒之地{/link}和{link:nethergarde-keep}守望堡{/link}的道路相交。每一支前往守望堡的{link:alliance}联盟{/link}商队都必须经过这里，而并非所有商队都能完好无损地通过。一支这样的商队的残骸就躺在路边，它的最后一名守卫仍在看守着失落者留下的东西。]=],
		},
	},
})

Translate("zhCN", "the-shifting-mire", {
	title = "流沙泥潭",
	sections = {
		{
			title = "概述",
			text = [=[流沙泥潭是{link:swamp-of-sorrows}沼泽{/link}{link:wetlands}湿地{/link}的中心，是{link:stonard}斯通纳德{/link}与西部道路之间由水塘和下陷地面构成的迷宫。它的小径随每一场雨而改变，任何关于它的地图都不会长久准确。年幼的鳄鱼在它的泥滩上晒太阳，悲伤蜘蛛在淹没的树木之间结网。斯通纳德的{link:orcs}兽人{/link}派斥候进入其中，并非所有斥候都能回来。]=],
		},
	},
})

Translate("zhCN", "itharius", {
	title = "伊萨里奥斯",
	subtitle = "绿龙军团之龙",
	found = "伊萨里奥斯的洞穴，在沼泽西南部",
	hint = "寻找住在沼泽西南部一个洞穴中的那条龙。",
	allegiance = "绿龙军团 · 伊瑟拉的军团",
	sections = {
		{
			title = "概述",
			text = [=[伊萨里奥斯是绿龙军团的一条龙，绿龙军团是守护{link:emerald-dream}翡翠梦境{/link}的{red:ysera}伊瑟拉{/red}的军团。他把巢穴安在{link:swamp-of-sorrows}沼泽{/link}西南边缘的一个洞穴里，远离他的其他同族守望的{link:pool-of-tears}泪水之池{/link}。他的军团中的雏龙在他门外的沼泽中睡觉。他很少谈起自己。他耐心而庄重，以凡人所做的选择来衡量他们。]=],
		},
		{
			title = "意义",
			text = [=[绿龙来到这片{link:swamp-of-sorrows}沼泽{/link}，是为了阻止{link:hakkar}哈卡{/link}的祭司把他们的神召唤回这个世界。他们中的大多数不容任何凡人靠近。伊萨里奥斯是他们的{link:the-night-watch}守望者{/link}中唯一一个以盟友身份与凡人交谈、并会请求他们帮助的。]=],
		},
		{
			title = "事迹",
			text = [=[• 他把巢穴安在{link:swamp-of-sorrows}沼泽{/link}边缘，与{link:pool-of-tears}泪水之池{/link}的巨龙们相隔甚远。
• 他通过一块誓言石从远方与凡人交谈，那是一块承载着他的军团使命的石头。
• 他照看着他的军团中年幼的雏龙。
• 他派他的凡人盟友远赴{link:winterspring}冬泉谷{/link}寻求帮助。]=],
		},
		{
			title = "未载之事",
			text = [=[没有记录说明伊萨里奥斯在这片{link:swamp-of-sorrows}沼泽{/link}中住了多久，也没有记录他为何把巢穴安在离{link:temple-of-atal-hakkar}沉没神庙{/link}如此遥远的地方。他的年龄和他在绿龙中的地位都无人知晓。]=],
		},
	},
	chapters = {
		{
			title = "誓言石",
			hint = "给这条龙带去一颗蕴含他一位同族精华的宝石。",
			text = [=[绿龙军团的伊兰尼库斯曾肩负使命，要阻止阿塔莱再次召唤出他们的神。那个使命失败了，神庙的腐化攫住了他。他心智中仍属于他自己的一部分被束缚在一颗宝石中，从淹没的厅堂中被带了出来。伊萨里奥斯通过一块誓言石索要这颗宝石。他不保证这条路会很短。他只说，一个值得拯救的灵魂，值得为之付出牺牲。]=],
		},
		{
			title = "为沉睡者发声",
			hint = "听从巨龙的建议，前往遥远的北方。",
			text = [=[伊兰尼库斯躺在沉睡与死亡之间，被困在一张梦魇之网中。他的精华已被严重污染，但伊萨里奥斯相信仍然能够触及他。他派他的盟友北上，前往{link:winterspring}冬泉谷{/link}东部的雪原，去找一位名叫{link:umbranse-the-spiritspeaker}灵语者阿姆布兰希{/link}的{link:humans}人类{/link}灵媒，他为死者代言。伊兰尼库斯并没有死，但伊萨里奥斯希望这样的天赋同样能够触及他。]=],
		},
	},
	mentions = {
		{ text = "伊兰尼库斯的精华" },
		{ text = "伊兰尼库斯的自述" },
		{ text = "{link:swamp-of-sorrows}沼泽{/link}中的梦尘，从他的军团的雏龙身上收集" },
	},
	bonds = {
		{ id = "eranikus", name = "伊兰尼库斯", note = "他试图救赎的一条同军团的龙" },
		{ id = "umbranse-the-spiritspeaker", name = "灵语者阿姆布兰希", note = "冬泉谷的一位凡人盟友" },
	},
})

Translate("zhCN", "fel-zerul", {
	title = "费泽鲁尔",
	subtitle = "大酋长的使者",
	found = "斯通纳德，在大厅中",
	hint = "与斯通纳德那位研究沉没神庙的兽人交谈。",
	allegiance = "部落 · 斯通纳德",
	sections = {
		{
			title = "概述",
			text = [=[费泽鲁尔是大酋长{link:thrall}萨尔{/link}派往{link:swamp-of-sorrows}悲伤沼泽{/link}的{link:orcs}兽人{/link}，去查明{link:temple-of-atal-hakkar}阿塔哈卡神庙{/link}发生了什么怪事。他来时以为会看到一座满是黑暗施法者的{link:trolls}巨魔{/link}神庙。他发现的却是一座湖，神庙沉在湖底，绿龙在岸边站岗。从那以后，他一直在{link:stonard}斯通纳德{/link}工作，从阿塔莱的零星遗物中拼凑出事情的来龙去脉。]=],
		},
		{
			title = "意义",
			text = [=[费泽鲁尔代表着一个想要理解其世界中各种力量的{link:horde}部落{/link}。他畏惧阿塔莱，但他也相信他们的法术有朝一日可能为部落所用。通过他耐心的研究，部落得知了领导神庙的那位{link:jammal-an-the-prophet}预言者{/link}，以及那个可能让{link:hakkar}血神{/link}归来的仪式。]=],
		},
		{
			title = "事迹",
			text = [=[• 他从{link:pool-of-tears}泪水之池{/link}周围收集阿塔莱的神像和神物。
• 他的斥候带回了一份用鲜血写在干皮上的流放判决。
• 他把神庙的遗物向北送到{link:the-hinterlands}辛特兰{/link}的一位被流放的阿塔莱祭司那里。
• 他派{link:horde}部落{/link}的勇士进入那座{link:temple-of-atal-hakkar}沉没的神庙{/link}本身。]=],
		},
		{ title = "未载之事", text = "关于费泽鲁尔在大酋长把他派到{link:swamp-of-sorrows}沼泽{/link}之前的生平，没有任何记载。" },
	},
	chapters = {
		{
			title = "池中的遗物",
			hint = "收集阿塔莱留在泪水之池岸边的东西。",
			text = [=[{link:stonard}斯通纳德{/link}没有人知道阿塔莱在他们的神庙里做了什么。费泽鲁尔只知道那里曾有强大的魔法在运作，而且出了严重的差错。他从躺在湖岸泥中的遗物开始。他一件一件地研究它们，试图弄清{link:trolls}巨魔{/link}们曾希望达成什么。]=],
		},
		{
			title = "流放者的警告",
			hint = "把神庙的遗物带给被阿塔莱驱逐的那个人。",
			text = [=[一名斥候给他带来了一份判决书，用鲜血写在风干的皮肉上。它点名了一位阿塔莱祭司，判他流放到{link:the-hinterlands}辛特兰{/link}的{link:witherbark-trolls}枯木巨魔{/link}之中。费泽鲁尔把遗物送到了那位流放者那里。传回来的答复十分沉重。流放者说，这些遗物是无害的。但大祭司{link:jammal-an-the-prophet}迦玛兰{/link}有一个预言，如果他为他的神物找到了正确的附魔，整个世界都将陷入危险。]=],
		},
		{
			title = "哈卡的神物",
			hint = "进入沉没的神庙，夺取阿塔莱的神物。",
			text = [=[{link:jammal-an-the-prophet}预言者迦玛兰{/link}相信，当{link:hakkar}哈卡{/link}归来时，这位神灵将赐予阿塔莱永恒的生命。费泽鲁尔称之为一个会提前招致毁灭的骗局。他所畏惧的与其说是预言本身，不如说是可能实现它的那些神物。他派{link:horde}部落{/link}的勇士深入神庙去夺取它们。当他们手握神物归来时，他把他们封为部落的勇士。]=],
		},
	},
	mentions = {
		{ text = "{link:pool-of-tears}泪水之池{/link}" },
		{ text = "{link:atal-ai-exile}阿塔莱流放者{/link}" },
		{ text = "回到费泽鲁尔那里" },
		{ text = "{link:temple-of-atal-hakkar}阿塔哈卡神庙{/link}" },
	},
	bonds = {
		{ id = "atal-ai-exile", name = "阿塔莱流放者", note = "为他解读遗物的被逐祭司" },
		{ id = "thrall", name = "萨尔", note = "派他前来的大酋长" },
	},
})

Translate("zhCN", "fallen-hero-of-the-horde", {
	title = "部落英雄的灵魂",
	subtitle = "沼泽之灵",
	found = "沼泽的南部边缘，在通往诅咒之地的道路旁",
	hint = "寻找在南方道路旁等待的那个不安的灵魂。",
	allegiance = "部落（生前）",
	aliases = { "英魂" },
	sections = {
		{
			title = "概述",
			text = [=[在向南通往{link:blasted-lands}诅咒之地{/link}的道路附近，站着一个{link:horde}部落{/link}战士的鬼魂。生前，他指挥着一个名为{link:thrall}萨尔{/link}之握的军团。他没有等待命令就率领军团进入了诅咒之地，结果军团全军覆没。如今他站在他倒下的地方，仍在等待那份从未到来的命令。他自己无法出手一击。他只能请求生者帮助，而且他对{link:alliance}联盟{/link}和部落的战士一视同仁地提出请求。]=],
		},
		{
			title = "意义",
			text = [=[部落英雄的灵魂见证了一场世上大多数人已经遗忘的战争。在{link:dark-portal}黑暗之门{/link}的废墟之外，恶魔仍在一个名为{link:razelikh-the-defiler}污染者拉瑟莱克{/link}的领主统治下控制着{link:blasted-lands}诅咒之地{/link}。部落英雄的灵魂比任何活着的人都更清楚这一点。他教导说，真正的敌人不是{link:alliance}联盟{/link}或{link:horde}部落{/link}，而是等待着双方的{link:burning-legion}燃烧军团{/link}。]=],
		},
		{
			title = "事迹",
			text = [=[• 他在命令送达之前就率领{link:thrall}萨尔{/link}之握军团进入了{link:blasted-lands}诅咒之地{/link}。
• 他号召生者解放他的部下的灵魂，打破恶魔领主的力量。
• 他欢迎{link:alliance}联盟{/link}与{link:horde}部落{/link}并肩对抗恶魔。
• 他考验各个种族的战士，并奖励那些证明自己配得上的人。]=],
		},
		{
			title = "未载之事",
			text = [=[关于这位战士在{link:thrall}萨尔{/link}之握被派往南方之前的生平，没有任何记载。{link:trey-lightforge}特雷{/link}博尔是否是他自己的名字，{link:kirith-the-damned}基利斯{/link}的灵魂没有说清楚。]=],
		},
	},
	chapters = {
		{
			title = "失踪的命令",
			hint = "查明那位阵亡指挥官从未收到的命令后来怎样了。",
			text = [=[死后，他只能想着那份命令。{link:stonard}斯通纳德{/link}的{link:dispatch-commander-ruag}分队指挥官鲁尔格{/link}发誓说他发出了命令。他的骑手在路上遭到{link:murlocs}鱼人{/link}伏击，只有一人幸存。那个幸存者{link:bengor}本戈尔{/link}几乎说不出话。他说，一个名叫{link:swamp-talker}沼泽空谈者{/link}的鱼人从他手中夺走了命令，向东逃进了一个洞穴。部落英雄的灵魂得知，他的部下本不必死。只要他当初等一等，他们之中本有十九人可以幸免。]=],
		},
		{
			title = "束缚之石",
			hint = "从诅咒之地的石头中解放阵亡军团的灵魂。",
			text = [=[恶魔不让{link:thrall}萨尔{/link}之握的士兵安息。他们的灵魂被束缚在散布于{link:blasted-lands}诅咒之地{/link}的石头中，一共十八块。只有当这些石头被打碎时，这些人才能找到安宁。当最后一块石头碎裂时，部落英雄的灵魂知道，他那笔长久的债已开始偿还。]=],
		},
		{
			title = "失踪的副官",
			hint = "查明那位始终未被找到的副官的命运。",
			text = [=[他的一名军官仍然下落不明。副官{link:kirith-the-damned}基利斯{/link}曾和他一起被关押在一个名叫{link:archmage-allistarj}阿利斯塔{/link}的恶魔的洞穴里，受尽折磨，但基利斯的意志在折磨下崩溃了。部落英雄的灵魂在自己的笼子里听到了他的惨叫，然后就再也听不到什么了。当基利斯的灵魂终于被找到时，它用一个名字作答：{link:trey-lightforge}特雷{/link}博尔。]=],
		},
		{
			title = "污染者",
			hint = "拼合破碎的护符，去面对诅咒之地的恶魔领主。",
			text = [=[{link:razelikh-the-defiler}污染者拉瑟莱克{/link}通过三个仆从统治着{link:blasted-lands}诅咒之地{/link}。每个仆从都戴着护符的三分之一，只要他们持有它，在恶魔的领地上就不会死去。部落英雄的灵魂派他的勇士去击败这三个仆从，把护符拼合完整，然后登上最高峰上的恶魔巢穴。当{link:defilers}污染者{/link}倒下时，部落英雄的灵魂要了他的角。他想用它来证明，在一个被战争撕裂的世界里，英雄依然存在。]=],
		},
	},
	mentions = {
		{ text = "堕落" },
		{ text = "蒙羞者" },
		{ text = "无谓的争吵，{link:alliance}联盟{/link}前来相助" },
		{ text = "悲伤的往事" },
		{ text = "昔日英雄，与下士桑德·裂蹄的灵魂一起" },
		{ text = "黑暗的掩护" },
		{ text = "恶魔猎手" },
		{ text = "回到{link:blasted-lands}诅咒之地{/link}" },
		{ text = "拼合破碎的护符" },
		{ text = "不安的灵魂" },
		{ text = "战士的情谊" },
		{ text = "向暗誓者开战" },
		{ text = "巫毒羽毛" },
	},
	bonds = {
		{ id = "dispatch-commander-ruag", name = "分队指挥官鲁尔格", note = "发出了那份从未送达的命令" },
		{ id = "bengor", name = "本戈尔", note = "携带命令的最后一名骑手" },
		{ id = "swamp-talker", name = "沼泽空谈者", note = "夺走了命令" },
		{ id = "corporal-thund-splithoof", name = "下士桑德·裂蹄", note = "他的部下之一" },
		{ id = "razelikh-the-defiler", name = "污染者拉瑟莱克", note = "仇敌" },
	},
})

