Translate("zhCN", "helgrum-the-swift", {
	title = "赫格拉姆",
	subtitle = "斯通纳德的信使长",
	found = "斯通纳德",
	hint = "与掌管斯通纳德信使的那位迅捷的兽人交谈。",
	allegiance = "部落 · 斯通纳德",
	aliases = { "赫格鲁姆" },
	sections = {
